function elevAt(keys, s, L) {
  const k = keys.concat([[L, keys[0][1]]]);
  for (let i = 1; i < k.length; i++) if (s <= k[i][0]) {
    const a = k[i - 1], b = k[i]; const t = (s - a[0]) / Math.max(1e-6, b[0] - a[0]);
    return a[1] + (b[1] - a[1]) * t * t * (3 - 2 * t);
  }
  return keys[0][1];
}

export const CIRCUITS = SPECS.map(spec => {
  const pts = GEO[spec.id];
  // cumulative distance along the outline (already scaled to the official length)
  const cum = [0];
  for (let i = 1; i < pts.length; i++) cum.push(cum[i - 1] + Math.hypot(pts[i][0] - pts[i - 1][0], pts[i][1] - pts[i - 1][1]));
  const L = cum[cum.length - 1] + Math.hypot(pts[0][0] - pts[pts.length - 1][0], pts[0][1] - pts[pts.length - 1][1]);
  const points = pts.map((p, i) => [p[0], p[1], +elevAt(spec.elev, cum[i] * spec.length / L, spec.length).toFixed(2)]);
  const c = Object.assign({}, spec, {
    points,
    cornerNames: spec.corners.map(([a, b, name]) => ({ f0: a / spec.length, f1: b / spec.length, name })),
  });
  if (spec.tunnelAt) c.tunnel = [spec.tunnelAt[0] / spec.length, spec.tunnelAt[1] / spec.length];
  return c;
});
